def classify_timeout_progress(
    stdout_text: str,
    stderr_text: str,
    sandbox_state: dict[str, Any] | None,
) -> str:
    """Bucket a timed-out run into progress classes for triage.

    The sandbox is consulted first so that silent child processes that still
    produced commits or preserve refs count as ``write_progress`` rather than
    ``no_output``.
    """
    if sandbox_state is not None:
        if sandbox_state.get("commits_ahead_of_base", 0) > 0:
            return "write_progress"
        if sandbox_state.get("preserve_refs"):
            return "write_progress"
        if sandbox_state.get("tracked_diff_names"):
            return "write_progress"
        if sandbox_state.get("status_short", "").strip():
            return "write_progress"

    if stdout_text.strip() or stderr_text.strip():
        return "read_only_progress"
    return "no_output"


def run_cmd(
    cmd: list[str],
    cwd: pathlib.Path | None,
    timeout: int | None = None,
    check: bool = True,
) -> subprocess.CompletedProcess[str]:
    proc = subprocess.run(
        cmd,
        cwd=cwd,
        timeout=timeout,
        text=True,
        capture_output=True,
    )
    if check and proc.returncode != 0:
        raise RuntimeError(
            f"command failed ({proc.returncode}): {' '.join(cmd)}\n"
            f"stdout:\n{proc.stdout}\nstderr:\n{proc.stderr}"
        )
    return proc


def run_cmd_streamed(
    cmd: list[str],
    cwd: pathlib.Path | None,
    timeout: int | None,
    stdout_path: pathlib.Path,
    stderr_path: pathlib.Path,
) -> subprocess.CompletedProcess[str]:
    """Like run_cmd but tees stdout/stderr to artifact files in real time.

    Fixes agent-8288cd1f: subprocess.run(capture_output=True, timeout=N) loses
    buffered output to SIGKILL when the child has not yet flushed by the
    deadline. Writing the data as it arrives means the artifact files reflect
    whatever was emitted up to the kill moment, regardless of termination.

    On TimeoutExpired the child is killed, drained, and the exception is
    re-raised with exc.stdout / exc.stderr populated from the on-disk
    captures so existing callers continue to work.
    """
    stdout_path.parent.mkdir(parents=True, exist_ok=True)
    stdout_f = stdout_path.open("w", encoding="utf-8")
    stderr_f = stderr_path.open("w", encoding="utf-8")
    stdout_buf: list[str] = []
    stderr_buf: list[str] = []

    proc = subprocess.Popen(
        cmd,
        cwd=cwd,
        text=True,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        bufsize=1,
    )

    def pump(stream, sink_file, sink_buf) -> None:
        try:
            for line in iter(stream.readline, ""):
                sink_buf.append(line)
                sink_file.write(line)
                sink_file.flush()
        finally:
            try:
                stream.close()
            except Exception:
                pass

    t_out = threading.Thread(target=pump, args=(proc.stdout, stdout_f, stdout_buf), daemon=True)
    t_err = threading.Thread(target=pump, args=(proc.stderr, stderr_f, stderr_buf), daemon=True)
    t_out.start()
    t_err.start()

    timed_out = False
    try:
        proc.wait(timeout=timeout)
    except subprocess.TimeoutExpired:
        timed_out = True
        proc.kill()
        proc.wait()

    t_out.join(timeout=5)
    t_err.join(timeout=5)
    stdout_f.close()
    stderr_f.close()

    stdout_text = "".join(stdout_buf)
    stderr_text = "".join(stderr_buf)

    if timed_out:
        exc = subprocess.TimeoutExpired(cmd, timeout, output=stdout_text, stderr=stderr_text)
        raise exc

    return subprocess.CompletedProcess(
        args=cmd,
        returncode=proc.returncode,
        stdout=stdout_text,
        stderr=stderr_text,
    )


def parse_last_json_object(text: str) -> dict[str, Any]:
    decoder = json.JSONDecoder()
    objects: list[dict[str, Any]] = []
    for idx, char in enumerate(text):
        if char != "{":
            continue
        try:
            value, _ = decoder.raw_decode(text[idx:])
        except json.JSONDecodeError:
            continue
        if isinstance(value, dict):
            objects.append(value)
    return objects[-1] if objects else {}


def extract_status(exit_code: int | None, parsed: dict[str, Any]) -> str:
    for key in ("status", "final_status", "FinalStatus"):
        value = parsed.get(key)
        if isinstance(value, str) and value:
            return value
    if exit_code == 0:
        return "unknown_success"
    return "execution_failed"


def first_string(obj: dict[str, Any], *keys: str) -> str:
    for key in keys:
        value = obj.get(key)
        if isinstance(value, str) and value:
            return value
    return ""


def safe_name(value: str) -> str:
    out = []
    for char in value:
        if char.isalnum() or char in ("-", "_", "."):
            out.append(char)
        else:
            out.append("_")
    return "".join(out)


def summarize(results: list[dict[str, Any]]) -> dict[str, Any]:
    total = len(results)
    status_counts: dict[str, int] = {}
    verified_pass = 0
    verified_fail = 0
    verified_timeout = 0
    verified_skipped = 0
    execute_success = 0
    dry_runs = 0
    durations = []

    by_arm: dict[str, dict[str, Any]] = {}
    by_task: dict[str, dict[str, Any]] = {}

    for result in results:
        status = result.get("status", "unknown")
        status_counts[status] = status_counts.get(status, 0) + 1
        if status == "success":
            execute_success += 1
        if status == "dry_run":
            dry_runs += 1
        if isinstance(result.get("duration_ms"), int):
            durations.append(result["duration_ms"])

        verify_status = (result.get("verify") or {}).get("status")
        if verify_status == "pass":
            verified_pass += 1
        elif verify_status == "fail":
            verified_fail += 1
        elif verify_status == "timeout":
            verified_timeout += 1
        else:
            verified_skipped += 1

        add_group(by_arm, result.get("arm_id", "unknown"), result, verify_status)
        add_group(by_task, result.get("task_id", "unknown"), result, verify_status)

    executable = verified_pass + verified_fail
    comparison_valid_results = [
        r for r in results if r.get("model_comparison_valid", True)
    ]
    excluded_task_ids = sorted(
        {
            r.get("task_id", "unknown")
            for r in results
            if not r.get("model_comparison_valid", True)
        }
    )
    return {
        "total_runs": total,
        "status_counts": status_counts,
        "execute_success": execute_success,
        "execute_success_rate": ratio(execute_success, total),
        "verified_pass": verified_pass,
        "verified_fail": verified_fail,
        "verified_timeout": verified_timeout,
        "verified_skipped": verified_skipped,
        "executable": executable,
        "verified_pass_rate": ratio(verified_pass, executable),
        "dry_runs": dry_runs,
        "avg_duration_ms": int(sum(durations) / len(durations)) if durations else 0,
        "by_arm": sorted(by_arm.values(), key=lambda item: item["id"]),
        "by_task": sorted(by_task.values(), key=lambda item: item["id"]),
        "model_comparison": model_comparison_summary(
            comparison_valid_results, excluded_task_ids
        ),
    }


def model_comparison_summary(
    results: list[dict[str, Any]], excluded_task_ids: list[str]
) -> dict[str, Any]:
    """Aggregate only tasks eligible for model-vs-model separability scoring.

    Tasks flagged ``model_comparison_valid: false`` in the manifest are
    excluded from these rollups per README section "Tasks invalid for
    model-comparison scoring" — their verifiers produce model-independent
    results and would otherwise pollute leaderboard aggregates.
    """
    verified_pass = 0
    verified_fail = 0
    verified_timeout = 0
    verified_skipped = 0
    by_arm: dict[str, dict[str, Any]] = {}
    by_task: dict[str, dict[str, Any]] = {}
    for result in results:
        verify_status = (result.get("verify") or {}).get("status")
        if verify_status == "pass":
            verified_pass += 1
        elif verify_status == "fail":
            verified_fail += 1
        elif verify_status == "timeout":
            verified_timeout += 1
        else:
            verified_skipped += 1
        add_group(by_arm, result.get("arm_id", "unknown"), result, verify_status)
        add_group(by_task, result.get("task_id", "unknown"), result, verify_status)
    executable = verified_pass + verified_fail
    return {
        "total_runs": len(results),
        "verified_pass": verified_pass,
        "verified_fail": verified_fail,
        "verified_timeout": verified_timeout,
        "verified_skipped": verified_skipped,
        "executable": executable,
        "verified_pass_rate": ratio(verified_pass, executable),
        "excluded_task_ids": excluded_task_ids,
        "by_arm": sorted(by_arm.values(), key=lambda item: item["id"]),
        "by_task": sorted(by_task.values(), key=lambda item: item["id"]),
    }


def add_group(
    groups: dict[str, dict[str, Any]],
    group_id: str,
    result: dict[str, Any],
    verify_status: str | None,
) -> None:
    group = groups.setdefault(
        group_id,
        {
            "id": group_id,
            "runs": 0,
            "execute_success": 0,
            "verified_pass": 0,
            "verified_fail": 0,
            "verified_timeout": 0,
            "verified_skipped": 0,
            "executable": 0,
            "verified_pass_rate": 0.0,
        },
    )
    group["runs"] += 1
    if result.get("status") == "success":
        group["execute_success"] += 1
    if verify_status == "pass":
        group["verified_pass"] += 1
    elif verify_status == "fail":
        group["verified_fail"] += 1
    elif verify_status == "timeout":
        group["verified_timeout"] += 1
    else:
        group["verified_skipped"] += 1
    group["executable"] = group["verified_pass"] + group["verified_fail"]
    group["verified_pass_rate"] = ratio(group["verified_pass"], group["executable"])


def ratio(num: int, den: int) -> float:
    if den <= 0:
        return 0.0
    return round(num / den, 4)


def print_result(result: dict[str, Any]) -> None:
    verify = (result.get("verify") or {}).get("status", "skipped")
    print(
        f"{result['run_id']}: status={result.get('status')} "
        f"verify={verify} duration={result.get('duration_ms')}ms"
    )


