426	func beadbenchCorpusEntryFromYAML(raw, beadID string) map[string]any {
427		var current map[string]any
428		inBeads := false
429		for _, rawLine := range strings.Split(raw, "\n") {
430			line := strings.TrimRight(rawLine, "\r")
431			line = strings.Split(line, "#")[0]
432			if strings.TrimSpace(line) == "" {
433				continue
434			}
435			if !inBeads {
436				if strings.TrimSuffix(strings.TrimSpace(line), ":") == "beads" {
437					inBeads = true
438				}
439				continue
440			}
441			stripped := strings.TrimLeft(line, " \t")
442			indent := len(line) - len(stripped)
443			if strings.HasPrefix(stripped, "- ") {
444				if current != nil {
445					if id, _ := current["id"].(string); id == beadID {
446						return current
447					}
448				}
449				current = map[string]any{}
450				stripped = strings.TrimPrefix(stripped, "- ")
451			} else if indent == 0 {
452				break
453			}
454			if current == nil {
455				continue
456			}
457			key, value, ok := strings.Cut(stripped, ":")
458			if !ok {
459				continue
460			}
461			current[strings.TrimSpace(key)] = strings.TrimSpace(strings.Trim(value, `"'`))
462		}
463		if current != nil {
464			if id, _ := current["id"].(string); id == beadID {
465				return current
466			}
467		}
468		return nil
469	}
